(987545, 118078, 27375, '<td valign="top">too funny, great idea</td>', 'too funny, great idea', '2004-11-03 00:08:25.000000', NULL, 1),
(987556, 118122, 9073, '<td valign="top">Getting them to stay upright must have been quite a struggle. A great image. 10</td>', 'Getting them to stay upright must have been quite a struggle. A great image. 10', '2004-11-03 00:14:53.000000', NULL, 1),
(987570, 117892, 9073, '<td valign="top">Besides the point that from this position the knight only has one square to move to, the dof really needed to be crisper throughout the frame.</td>', 'Besides the point that from this position the knight only has one square to move to, the dof really needed to be crisper throughout the frame.', '2004-11-03 00:21:35.000000', NULL, 1),
(987573, 118109, 22748, '<td valign="top">Great idea and composition, but there''s a lot of color noise, and the blurry hand is distracting.</td>', 'Great idea and composition, but there''s a lot of color noise, and the blurry hand is distracting.', '2004-11-03 00:22:49.000000', NULL, 1),
