(987580, 117988, 22748, '<td valign="top">Weird! Is it made of glass? Interesting.</td>', 'Weird! Is it made of glass? Interesting.', '2004-11-03 00:23:36.000000', NULL, 1),
(987582, 117928, 22748, '<td valign="top">It''s a little dark and the lighting is flat and harsh. Did you use the onboard flash? That would be the problem.</td>', 'It''s a little dark and the lighting is flat and harsh. Did you use the onboard flash? That would be the problem.', '2004-11-03 00:24:30.000000', NULL, 1),
