(987654, 117911, 6519, '<td valign="top">Very likely scenario at this time (just after Halloween) and I like the very tight crop. Nice and clear.</td>', 'Very likely scenario at this time (just after Halloween) and I like the very tight crop. Nice and clear.', '2004-11-03 00:46:59.000000', NULL, 1),
(987660, 118145, 27293, '<td valign="top">Having worked as a bartender for a while, i don''t think there is a person that would even think about cognac, bourbon and scotch at the same time... Now, jack or jim -- that would be plausible.</td>', 'Having worked as a bartender for a while, i don''t think there is a person that would even think about cognac, bourbon and scotch at the same time... Now, jack or jim -- that would be plausible.', '2004-11-03 00:47:57.000000', NULL, 1),
(987664, 117893, 6519, '<td valign="top">Great twist on an obvious "Indecision" scenario.</td>', 'Great twist on an obvious "Indecision" scenario.', '2004-11-03 00:48:45.000000', NULL, 1),
(987673, 117975, 6519, '<td valign="top">I like it! I can almost feel the dog think: "Hmmm..... should I bother?" Nice DOF and the leading line path makes my eyes keep going back and forth between the subjects.</td>', 'I like it! I can almost feel the dog think: "Hmmm..... should I bother?" Nice DOF and the leading line path makes my eyes keep going back and forth between the subjects.', '2004-11-03 00:52:21.000000', NULL, 1),
