(988853, 118191, 16648, '<td valign="top">too dark - the monument needs to be seen to make the point of the pic - and yes, i have a calibrated monitor.</td>', 'too dark - the monument needs to be seen to make the point of the pic - and yes, i have a calibrated monitor.', '2004-11-03 12:42:45.000000', NULL, 1),
(988856, 118118, 16648, '<td valign="top">Why the weird coloration?</td>', 'Why the weird coloration?', '2004-11-03 12:44:04.000000', NULL, 1),
(988858, 117942, 16648, '<td valign="top">ooooh - she is blurry, the wall in the back is out of focus...the gent in the back is not focused well either, and white balance appears off (a yellowish cast) and the background is distracting, the hands or ?? on the left should be cropped out....need i go on?</td>', 'ooooh - she is blurry, the wall in the back is out of focus...the gent in the back is not focused well either, and white balance appears off (a yellowish cast) and the background is distracting, the hands or ?? on the left should be cropped out....need i go on?', '2004-11-03 12:45:45.000000', NULL, 1),
(988863, 117874, 16648, '<td valign="top">Hurts my eyes - too saturated? not well focused?</td>', 'Hurts my eyes - too saturated? not well focused?', '2004-11-03 12:47:22.000000', NULL, 1),
(988866, 118134, 16648, '<td valign="top">could use a bit more light, a bit more sharpening</td>', 'could use a bit more light, a bit more sharpening', '2004-11-03 12:47:53.000000', NULL, 1),
(988872, 118185, 16648, '<td valign="top">the light is a bit too harsh</td>', 'the light is a bit too harsh', '2004-11-03 12:50:55.000000', NULL, 1),
