(989008, 117923, 1, '<td valign="top">The objects at the top are too dark.  They shoudl either be easily visible or removed from the picture.</td>', 'The objects at the top are too dark.  They shoudl either be easily visible or removed from the picture.', '2004-11-03 13:45:59.000000', NULL, 1),
(989009, 117911, 1, '<td valign="top">The shadows are really hurting this photo.  Another light source directly on the apple and 3 musketeers logo would''ve been better imo.</td>', 'The shadows are really hurting this photo.  Another light source directly on the apple and 3 musketeers logo would''ve been better imo.', '2004-11-03 13:47:28.000000', NULL, 1),
