(994115, 118209, 6667, '<td valign="top">Is this really indecision. . . or the final solution?!  Excellent phot.  BOL</td>', 'Is this really indecision. . . or the final solution?!  Excellent phot.  BOL', '2004-11-05 20:40:38.000000', NULL, 1),
(994123, 118144, 6667, '<td valign="top">Very, very clever interpretation.  Love the rich contrast in the black and white.  I would have rated this even higher had the chair been turned as if she were waiting for the viewer to be seated for the hair cut?  Faced this way the scene does not fit the title.  7 BOL  One added comment: I find the thin white boarder  somewhat distracting especially around the top and right.  Only minor though.</td>', 'Very, very clever interpretation.  Love the rich contrast in the black and white.  I would have rated this even higher had the chair been turned as if she were waiting for the viewer to be seated for the hair cut?  Faced this way the scene does not fit the title.  7 BOL  One added comment: I find the thin white boarder  somewhat distracting especially around the top and right.  Only minor though.', '2004-11-05 20:49:37.000000', NULL, 1),
(994125, 118026, 6667, '<td valign="top">Great image. . . but you needed  an Alice!</td>', 'Great image. . . but you needed  an Alice!', '2004-11-05 20:50:42.000000', NULL, 1),
(994126, 118082, 6667, '<td valign="top">Excellent 7 . . . Terrible 0  neat idea.</td>', 'Excellent 7 . . . Terrible 0  neat idea.', '2004-11-05 20:52:10.000000', NULL, 1),
