(994403, 118174, 22010, '<td valign="top">Good concept, nice title. Colors are wonderful. Technically excellent! My top pick thus far.</td>', 'Good concept, nice title. Colors are wonderful. Technically excellent! My top pick thus far.', '2004-11-05 23:40:11.000000', NULL, 1),
(994404, 118190, 10275, '<td valign="top">Very good composition. Nice idea. Skins tones are a bit red. Nice detail.</td>', 'Very good composition. Nice idea. Skins tones are a bit red. Nice detail.', '2004-11-05 23:40:29.000000', NULL, 1),
(994406, 118104, 10275, '<td valign="top">Very very nice. Lovely take on this challenge. I love the way her face is lit. Nice detail in her upper body. Great soft colours. Well done.</td>', 'Very very nice. Lovely take on this challenge. I love the way her face is lit. Nice detail in her upper body. Great soft colours. Well done.', '2004-11-05 23:41:23.000000', NULL, 1),
