(994490, 117814, 23300, '<td valign="top">The blur is very effective in communicating the sense of beiing drunk.</td>', 'The blur is very effective in communicating the sense of beiing drunk.', '2004-11-06 00:17:18.000000', NULL, 1),
(994496, 118000, 23300, '<td valign="top">The colouring and composition really enhance the mood of the image. The composition is well balanced also.</td>', 'The colouring and composition really enhance the mood of the image. The composition is well balanced also.', '2004-11-06 00:21:12.000000', NULL, 1),
(994508, 118118, 23300, '<td valign="top">The overall green colour works well to add a sort of "matrix" feel to the image. The saturation of the colour of the pills does make them look a abit out of place to me. The overall composition works well.</td>', 'The overall green colour works well to add a sort of "matrix" feel to the image. The saturation of the colour of the pills does make them look a abit out of place to me. The overall composition works well.', '2004-11-06 00:27:28.000000', NULL, 1),
(994509, 118205, 24846, '<td valign="top">Life is indeed worth living, even by imperfect people in an imperfect world...<br/>Great literate take on this subject. Love the richness of the page and text. Great dof yielding the sharp text. -10-</td>', 'Life is indeed worth living, even by imperfect people in an imperfect world...Great literate take on this subject. Love the richness of the page and text. Great dof yielding the sharp text. -10-', '2004-11-06 00:28:01.000000', NULL, 1),
(994511, 117995, 23300, '<td valign="top">I quite like the "painted" effect. I think you have handled the filter well. The composition works well and the girl''s expression is very effective. I would love to see this image without the products in the way. I think her face is quite expressive and would make a good image by itself. Good luck.</td>', 'I quite like the "painted" effect. I think you have handled the filter well. The composition works well and the girl''s expression is very effective. I would love to see this image without the products in the way. I think her face is quite expressive and would make a good image by itself. Good luck.', '2004-11-06 00:30:58.000000', NULL, 1),
(994513, 118174, 23300, '<td valign="top">Nice use of texture and light.</td>', 'Nice use of texture and light.', '2004-11-06 00:31:39.000000', NULL, 1),
(994518, 118129, 23300, '<td valign="top">I like the composition of this image. The use of black and white is effective too. I think the blur does not really enhance the image though.</td>', 'I like the composition of this image. The use of black and white is effective too. I think the blur does not really enhance the image though.', '2004-11-06 00:37:06.000000', NULL, 1),
(994520, 117903, 23300, '<td valign="top">The composition and stark lighting are very effective in drawing attention to the text.</td>', 'The composition and stark lighting are very effective in drawing attention to the text.', '2004-11-06 00:39:29.000000', NULL, 1),
(994522, 118108, 23300, '<td valign="top">The composition and lighting are very powerful in enhancing the subject matter. They give the image a sense of importance as though the decision at hand is quite compelling.</td>', 'The composition and lighting are very powerful in enhancing the subject matter. They give the image a sense of importance as though the decision at hand is quite compelling.', '2004-11-06 00:42:34.000000', NULL, 1),
(994523, 117808, 4267, '<td valign="top">actually that party is the most evil... the photo doesn''t fit with the title.. lol</td>', 'actually that party is the most evil... the photo doesn''t fit with the title.. lol', '2004-11-06 00:42:39.000000', NULL, 1),
(994525, 118153, 4267, '<td valign="top">the hand casting a showdow on the face is kinda of distracting</td>', 'the hand casting a showdow on the face is kinda of distracting', '2004-11-06 00:43:24.000000', NULL, 1),
(994526, 117980, 4267, '<td valign="top">little blurry</td>', 'little blurry', '2004-11-06 00:43:38.000000', NULL, 1),
(994527, 117999, 4267, '<td valign="top">looks like the decision has been made rather than an indecision at stake</td>', 'looks like the decision has been made rather than an indecision at stake', '2004-11-06 00:44:34.000000', NULL, 1),
(994529, 118155, 23300, '<td valign="top">I really like the fact that the flag is over her mouth. The implications suggested by this could lead to very lengthy and in depth discussions. The image has a sort of comical quality that I don''t think is wasted on the topic. I assume there are no prizes for guessing which way you will be voting.</td>', 'I really like the fact that the flag is over her mouth. The implications suggested by this could lead to very lengthy and in depth discussions. The image has a sort of comical quality that I don''t think is wasted on the topic. I assume there are no prizes for guessing which way you will be voting.', '2004-11-06 00:45:33.000000', NULL, 1),
(994530, 118121, 4267, '<td valign="top">relies too much on the title to show the indecision... rather the photo looks like he has made up his mind</td>', 'relies too much on the title to show the indecision... rather the photo looks like he has made up his mind', '2004-11-06 00:46:00.000000', NULL, 1);
