(995043, 118122, 24363, '<td valign="top">very original, i like it</td>', 'very original, i like it', '2004-11-06 10:08:57.000000', NULL, 1),
(995049, 118131, 25150, '<td valign="top">great slow shutter work. The title really explains it all! I think I would like it a bit more if there was something going on in the top right, but i definately like the crookedness of the who shot!<br/>Keep up the good work :)</td>', 'great slow shutter work. The title really explains it all! I think I would like it a bit more if there was something going on in the top right, but i definately like the crookedness of the who shot!Keep up the good work :)', '2004-11-06 10:23:05.000000', NULL, 1),
(995050, 117980, 25150, '<td valign="top">the expression is so perfect for this challenge. The only problem i see is the overall grainyness of the shot. especially in the shadow behind (you?) good job overall!</td>', 'the expression is so perfect for this challenge. The only problem i see is the overall grainyness of the shot. especially in the shadow behind (you?) good job overall!', '2004-11-06 10:24:51.000000', NULL, 1),
