(998652, 117928, 27939, '<td valign="top">This doesn''t have impact on me, furry at the edges and in the middle, more DOF and a little more contrast would make a big improvement on this subject</td>', 'This doesn''t have impact on me, furry at the edges and in the middle, more DOF and a little more contrast would make a big improvement on this subject', '2004-11-08 09:02:27.000000', NULL, 1),
